// The user's Garbh Sanskar.xlsx (2026-10-13): lib/data/garbh_sheet.dart,
// generated by tools/garbh_content/xlsx_to_dart.py.
//
// Holds: every day 1–280 is there once and complete; nothing the user ruled
// out reached a screen (the sheet's claim columns, NIV wording, placeholder
// "(Full hymn)" texts); the mother's card, her daily screen and the father's
// card read the same day; today's story is on the door; each faith gained its
// section; and it is wired.
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:parentveda/data/doors/pv_door_data.dart';
import 'package:parentveda/data/doors/pv_door_garbh.dart';
import 'package:parentveda/data/garbh_data.dart';
import 'package:parentveda/data/garbh_sheet.dart';
import 'package:parentveda/data/spiritual_reading_data.dart';

void main() {
  group('the days', () {
    test('every day of pregnancy, once, complete', () {
      expect(kGarbhSheetDays, hasLength(280));
      for (var i = 0; i < 280; i++) {
        final d = kGarbhSheetDays[i];
        expect(d.day, i + 1);
        for (final s in [d.mother, d.father, d.storyTitle, d.story, d.storyClose]) {
          expect(s.trim(), isNotEmpty, reason: 'day ${d.day}');
        }
      }
    });

    test('the story is split from the line it closes on, never at an opening quote', () {
      for (final d in kGarbhSheetDays) {
        expect(d.story, matches(RegExp(r'[.!?"”]$')), reason: 'day ${d.day}');
        expect(d.storyClose, matches(RegExp(r'^[A-Z]')), reason: 'day ${d.day}');
        expect(d.storyClose.length, lessThan(200), reason: 'day ${d.day}: the close is a line, not the story');
      }
      expect(garbhSheetDay(1).storyClose, startsWith('True strength grows'));
    });

    test('days are held to 1–280', () {
      expect(garbhSheetDay(0).day, 1);
      expect(garbhSheetDay(400).day, 280);
    });
  });

  group('what the user ruled out stays out', () {
    final all = <String>[
      for (final d in kGarbhSheetDays) ...[d.mother, d.father, d.storyTitle, d.story, d.storyClose],
      for (final list in kGarbhMantrasByTradition.values)
        for (final m in list) ...[m.name, m.text, m.meaning],
      for (final s in [...kGarbhSacredStories, ...kGarbhGitaConversations]) ...[s.title, s.source, s.story, s.moral],
    ];

    test('no claim column text, no audio claims', () {
      final claims = RegExp(r'cortisol|\b\d{3} ?Hz\b|Solfeggio|\bIQ\b|nervous system|brain development|'
          r'intellectual potential|cellular development|Prenatal Intent|Developmental Focus', caseSensitive: false);
      for (final s in all) {
        expect(claims.hasMatch(s), isFalse, reason: s);
      }
    });

    test('no NIV wording, and no placeholder in place of a text', () {
      for (final s in all) {
        expect(s.contains('you knit me together in my mother’s womb. I praise you'), isFalse);
        expect(s.contains('Whoever dwells in the shelter of the Most High'), isFalse);
        expect(RegExp(r'^\((Full hymn|Hymn of|Various verses|Recitation)').hasMatch(s), isFalse, reason: s);
      }
      expect(kGarbhMantrasChristian.first.text, contains('You knit me together'));
      expect(kGarbhMantrasChristian.first.name, contains('Psalm 139:13-14'));
    });

    test('no mantra is listed twice', () {
      for (final e in kGarbhMantrasByTradition.entries) {
        final texts = e.value.map((m) => m.text.toLowerCase()).toList();
        expect(texts.toSet().length, texts.length, reason: e.key);
      }
    });
  });

  group('where it shows', () {
    test('her card names today\'s line, with a short title, never the whole text', () {
      for (final day in [1, 90, 200, 280]) {
        final p = promptForDay(day, 2);
        expect(p.text.en, garbhSheetDay(day).mother);
        expect(p.title.en.length, lessThanOrEqualTo(57), reason: 'day $day: "${p.title.en}"');
        expect(p.id, 'gsday_$day');
      }
    });

    test('today\'s story is a row in Talk and read, and opens as a piece', () {
      final read = kGarbhDoor.sections.where((s) => s.group == kGarbhTabRead);
      final ids = [
        for (final s in read)
          for (final t in s.tiles)
            if (t is PvDoorReadTile) t.surfaceId,
      ];
      expect(ids, contains(kGarbhSurfaceStoryToday));
      final story = garbhStoryForDay(42);
      expect(story.title.en, garbhSheetDay(42).storyTitle);
      expect(story.text.en, contains(garbhSheetDay(42).storyClose));
    });

    test('each faith gains its section; Hinduism its stories and Gita conversations', () {
      SpiritualTradition t(String id) => kSpiritualTraditions.firstWhere((x) => x.id == id);
      expect(t('hindu').sections.map((s) => s.title.en),
          containsAll(['Mantras and prayers', 'Sacred stories, retold', 'Gita conversations, retold']));
      expect(t('sikh').sections.map((s) => s.title.en), contains('Shabads and prayers'));
      expect(t('islam').sections.map((s) => s.title.en), contains('Duas and verses'));
      expect(t('christian').sections.map((s) => s.title.en), contains('Scripture and prayers'));
      // The authored sections are untouched and come first.
      expect(t('hindu').sections.first.title.en, 'Reflections inspired by the Gita');
      expect(t('jain').sections.map((s) => s.title.en), isNot(contains('Mantras and prayers')));
    });
  });

  test('wired: her screen, his card and tab, the router, the library', () {
    String src(String p) => File(p).readAsStringSync();
    expect(src('lib/screens/garbh_samvad_daily.dart'), contains('return promptForDay(day, _trimester);'));
    expect(src('lib/screens/father/father_daily_screen.dart'), contains('garbhSheetDay(widget.controller.currentDay)'));
    expect(src('lib/screens/father/father_read_aloud_screen.dart'), contains('garbhSheetDay(widget.controller.currentDay).father'));
    expect(src('lib/screens/doors/pv_door_router.dart'), contains('piece: garbhStoryForDay(c.currentDay)'));
    expect(src('lib/screens/garbh_screen.dart'), contains("saveKey: 'gsstory_\$d'"));
    expect(src('lib/screens/garbh/garbh_today_practice.dart'), contains('promptForDay(day, garbhTrimester(week))'));
  });
}
